from typing import List
class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        groups = [[] for _ in range(n + 1)]
        for i, (a, b) in enumerate(conflictingPairs):
            lo, hi = (a, b) if a < b else (b, a)
            groups[hi].append((lo, i))
        b1v, b1i, b2v = 0, -1, 0
        base = 0
        add = {}
        for r in range(1, n + 1):
            for v, i in groups[r]:
                if v > b1v:
                    b2v = b1v
                    b1v, b1i = v, i
                elif v > b2v:
                    b2v = v
            base += r - b1v
            if b1i >= 0:
                add[b1i] = add.get(b1i, 0) + (b1v - b2v)
        best = max(add.values()) if add else 0
        return base + best

