import sys
def solve(n, g):
    Pin=[[0]*n for _ in range(26)]; Pout=[[0]*n for _ in range(26)]
    for u in range(n):
        for v in range(n):
            ch=g[u][v]
            if ch!='-':
                c=ord(ch)-97; Pin[c][v]|=1<<u; Pout[c][u]|=1<<v
    vis=[0]*n; D=[[-1]*n for _ in range(n)]
    maxd=2*n*n+6; buckets=[[] for _ in range(maxd+3)]
    def assign(u,v,d):
        vis[u]|=1<<v; D[u][v]=d; buckets[d].append((u,v))
    for u in range(n): assign(u,u,0)
    for u in range(n):
        for v in range(n):
            if g[u][v]!='-' and u!=v and not (vis[u]>>v)&1: assign(u,v,1)
    for d in range(maxd+1):
        for (a,b) in buckets[d]:
            for c in range(26):
                U=Pin[c][a]
                if not U: continue
                V=Pout[c][b]
                if not V: continue
                while U:
                    low=U&-U; u=low.bit_length()-1; U^=low
                    nb=V & ~vis[u]
                    if nb:
                        vis[u]|=nb
                        while nb:
                            lo=nb&-nb; v=lo.bit_length()-1; nb^=lo
                            D[u][v]=d+2; buckets[d+2].append((u,v))
    return D

