def main():
    MOD=998244353
    data=sys.stdin.read().split()
    N,M,K=int(data[0]),int(data[1]),int(data[2])
    X=[int(v) for v in data[3:3+M]]
    S=[[0]*(K+1) for _ in range(N+2)]
    S[0][0]=1
    for i in range(1,N+2):
        for j in range(1,min(i,K)+1):
            S[i][j]=(S[i-1][j-1]+j*S[i-1][j])%MOD
    fk2=factorial(K-2)%MOD
    def P(u):
        if u<K-1: return 0
        return (K-1)*fk2*S[u-1][K-2]%MOD
    Pl=[0]*(N+1)
    for u in range(1,N+1): Pl[u]=P(u)
    def fvec(same):
        res=[0]*(N+1)
        if same:
            T=[pow(K-1,v,MOD) for v in range(N+1)]
        else:
            T=[(pow(K-1,v,MOD)-pow(K-2,v,MOD))%MOD for v in range(N+1)]
        for l in range(1,N+1):
            tot=0
            for u in range(1,l):
                v=l-1-u
                if Pl[u]: tot+=Pl[u]*T[v]
            res[l]=tot%MOD
        return res
    fs={True:fvec(True),False:fvec(False)}
    W=10
    def pack(a):
        return int.from_bytes(b''.join(x.to_bytes(W,'little') for x in a),'little')
    def unpack(v,n):
        L=n*W+W*2
        bs=v.to_bytes(max(L,(v.bit_length()+7)//8+W),'little')
        return [int.from_bytes(bs[W*i:W*i+W],'little')%MOD for i in range(n)]
    def mul(a,b):
        v=pack(a)*pack(b)
        return unpack(v,N+1)
    cur=[0]*(N+1); cur[0]=1
    for j in range(M-1):
        same = (X[j]==X[j+1])
        cur=mul(cur,fs[same])
    fk=factorial(K-1)%MOD
    ans=0
    for a in range(N+1):
        if cur[a]:
            r=N-a
            g=fk*S[r][K-1]%MOD
            ans+=cur[a]*g
    print(ans%MOD)
