class Solution:
    def lenOfVDiagonal(self, grid: List[List[int]]) -> int:
        n = len(grid); m = len(grid[0])
        D = [(1,1),(1,-1),(-1,-1),(-1,1)]  # clockwise order
        def valid(a, b):
            return b == 0 if a == 2 else b == 2
        B = []; A = []
        for k in range(4):
            dr, dc = D[k]
            Bk = [[0]*m for _ in range(n)]
            rows = range(n) if dr != -1 else range(n-1, -1, -1)
            cols = range(m) if dc != -1 else range(m-1, -1, -1)
            for r in rows:
                Br = Bk[r]
                pr = r - dr
                for c in cols:
                    g = grid[r][c]
                    if g == 1:
                        Br[c] = 1
                        continue
                    pc = c - dc
                    if 0 <= pr < n and 0 <= pc < m and Bk[pr][pc] > 0 and valid(grid[pr][pc], g):
                        Br[c] = Bk[pr][pc] + 1
            B.append(Bk)
        for k in range(4):
            dr, dc = D[k]
            Ak = [[1]*m for _ in range(n)]
            rows = range(n-1, -1, -1) if dr != -1 else range(n)
            cols = range(m-1, -1, -1) if dc != -1 else range(m)
            for r in rows:
                Ar = Ak[r]
                sr = r + dr
                for c in cols:
                    sc = c + dc
                    if 0 <= sr < n and 0 <= sc < m and valid(grid[r][c], grid[sr][sc]):
                        Ar[c] = Ak[sr][sc] + 1
            A.append(Ak)
        best = 0
        for k in range(4):
            Bk = B[k]; Ak1 = A[(k+1) % 4]
            for r in range(n):
                for c in range(m):
                    b = Bk[r][c]
                    if b > best: best = b
                    if b > 0:
                        t = b + Ak1[r][c] - 1
                        if t > best: best = t
        return best

