from functools import lru_cache
from typing import List
class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        @lru_cache(maxsize=None)
        def f(o, e, p):
            if o == 0 and e == 0:
                return 1
            if p == 1:
                return e * f(o, e - 1, 0) if e > 0 else 0
            return o * f(o - 1, e, 1) if o > 0 else 0
        o = (n + 1) // 2
        e = n // 2
        used = [False] * (n + 1)
        res = []
        lp = -1
        for pos in range(n):
            chosen = False
            for v in range(1, n + 1):
                if used[v]:
                    continue
                if lp != -1 and v % 2 == lp:
                    continue
                par = v % 2
                o2 = o - par
                e2 = e - (1 - par)
                c = f(o2, e2, par)
                if k <= c:
                    used[v] = True
                    res.append(v)
                    o, e = o2, e2
                    lp = par
                    chosen = True
                    break
                k -= c
            if not chosen:
                return []
        return res

