    def largestPalindrome(self, n: int, k: int) -> str:
        h = (n + 1) // 2
        w = []
        for i in range(h):
            j = n - 1 - i
            if i == j:
                w.append(pow(10, i, k))
            else:
                w.append((pow(10, i, k) + pow(10, j, k)) % k)
        S = [None] * (h + 1)
        S[h] = [False] * k
        S[h][0] = True
        for i in range(h - 1, -1, -1):
            cur = [False] * k
            nxt = S[i + 1]
            for r in range(k):
                if nxt[r]:
                    for d in range(10):
                        cur[(r + d * w[i]) % k] = True
            S[i] = cur
        digits = []
        cr = 0
        for i in range(h):
            lo = 1 if i == 0 else 0
            chosen = False
            for d in range(9, lo - 1, -1):
                nr = (cr + d * w[i]) % k
                if S[i + 1][(-nr) % k]:
                    digits.append(d)
                    cr = nr
                    chosen = True
                    break
            if not chosen:
                return ""
        s = ''.join(map(str, digits))
        return s + s[:n // 2][::-1]

