from typing import List
class Solution:
    def countNonDecreasingSubarrays(self, nums: List[int], k: int) -> int:
        n = len(nums)
        N = n + 2
        B1 = [0]*(N+1); B2 = [0]*(N+1)
        def upd(B, i, x):
            while i <= N:
                B[i] += x; i += i & -i
        def pre(B, i):
            s = 0
            while i > 0:
                s += B[i]; i -= i & -i
            return s
        def radd(l, r, x):
            upd(B1, l, x); upd(B1, r+1, -x)
            upd(B2, l, x*(l-1)); upd(B2, r+1, -x*r)
        def psum(i):
            return pre(B1, i)*i - pre(B2, i)
        def cost(l, r):
            return psum(r+1) - psum(l)
        stack = []
        r = n-1
        ans = 0
        for l in range(n-1, -1, -1):
            v = nums[l]
            end = l
            while stack and stack[-1][2] <= v:
                s, e, c = stack.pop()
                if c != v:
                    radd(s+1, e+1, v-c)
                end = e
            stack.append([l, end, v])
            while cost(l, r) > k:
                r -= 1
            ans += r - l + 1
        return ans

