def solve_prefix(arr):
    n = len(arr)
    order = sorted(range(n), key=lambda i: (arr[i], i))
    rank = [0]*n
    for r, i in enumerate(order, 1):
        rank[i] = r
    cnt = [0]*(n+1); sm = [0]*(n+1)
    LOG = 1
    while LOG*2 <= n: LOG *= 2
    res = [0]*(n+1)
    total = 0; m = 0
    for i in range(n):
        x = arr[i]; r = rank[i]
        total += x; m += 1
        p = r
        while p <= n:
            cnt[p] += 1; sm[p] += x; p += p & -p
        if m % 2 == 0:
            h = m // 2
            pos = 0; rem = h; s = 0; step = LOG
            while step:
                np_ = pos + step
                if np_ <= n and cnt[np_] <= rem:
                    pos = np_; rem -= cnt[np_]; s += sm[np_]
                step >>= 1
            res[m] = total - 2*s
    return res

def solve(A):
    n = len(A)
    pre = solve_prefix(A)
    if n % 2 == 0:
        return pre[n]
    suf = solve_prefix(A[::-1])
    best = 0
    for j in range(0, n, 2):
        v = pre[j] + suf[n-1-j]
        if v > best: best = v
    return best

