    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        INF = float('inf')
        minv = [INF]*k
        minv[0] = 0
        P = 0
        ans = -INF
        for j in range(1, len(nums)+1):
            P += nums[j-1]
            r = j % k
            if minv[r] != INF:
                v = P - minv[r]
                if v > ans:
                    ans = v
            if P < minv[r]:
