def brute(nums):
    def can(x, y):
        if x == y: return True
        sx, sy = str(x), str(y)
        L = max(len(sx), len(sy))
        sx = sx.zfill(L); sy = sy.zfill(L)
        def sw(s):
            out = []
            for i in range(L):
                for j in range(L):
                    t = list(s); t[i], t[j] = t[j], t[i]
                    out.append(int(''.join(t)))
            return out
        return y in sw(sx) or x in sw(sy)
    c = 0
    for i in range(len(nums)):
        for j in range(i+1, len(nums)):
            if can(nums[i], nums[j]): c += 1
    return c

