import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        N = 10000
        sieve = [True] * N
        sieve[0] = sieve[1] = False
        for i in range(2, 100):
            if sieve[i]:
                for j in range(i * i, N, i):
                    sieve[j] = False
        if sieve[n] or sieve[m]:
            return -1
        L = len(str(n))
        INF = float('inf')
        dist = {n: n}
        pq = [(n, n)]
        while pq:
            d, u = heapq.heappop(pq)
            if d != dist.get(u):
                continue
            if u == m:
                return d
            for pos in range(L):
                pw = 10 ** (L - 1 - pos)
                dig = (u // pw) % 10
                for nd in (dig - 1, dig + 1):
                    if 0 <= nd <= 9:
                        v = u + (nd - dig) * pw
                        if sieve[v]:
                            continue
                        nd2 = d + v
                        if nd2 < dist.get(v, INF):
                            dist[v] = nd2
                            heapq.heappush(pq, (nd2, v))
        return -1

