class Solution:
    def beautifulSplits(self, nums):
        n = len(nums)
        if n < 3: return 0
        z = [0]*n
        z[0] = n
        l = r = 0
        for i in range(1, n):
            if i < r:
                z[i] = min(r-i, z[i-l])
            while i+z[i] < n and nums[z[i]] == nums[i+z[i]]:
                z[i] += 1
            if i+z[i] > r:
                l, r = i, i+z[i]
        prev = [0]*(n+1)
        total = 0
        for i in range(n-1, 0, -1):
            a = nums[i]
            cur = [0]*(n+1)
            if i+1 < n:
                cur[i+1:n] = [(p+1) if nums[j]==a else 0 for j, p in zip(range(i+1, n), prev[i+2:n+1])]
            prev = cur
            if i <= n-2:
                B = 0
                ov = 0
                zi = z[i] >= i
                for j in range(i+1, n):
                    if cur[j] >= j-i:
                        B += 1
                        if zi and j >= 2*i:
                            ov += 1
                A = (n-2*i) if (zi and n-2*i > 0) else 0
                total += A + B - ov
        return total

