def fast(N, W, blocks, queries):
    cols = [[] for _ in range(W + 1)]
    for i, (x, y) in enumerate(blocks):
        cols[x].append((y, i))
    for c in cols[1:]:
        c.sort()
    K = min(len(cols[x]) for x in range(1, W + 1))
    rank = [0] * N
    D = [0] * (K + 1)
    for x in range(1, W + 1):
        for k, (y, i) in enumerate(cols[x], 1):
            rank[i] = k
            if k <= K:
                z = y - k
                if z > D[k]:
                    D[k] = z
    tau = [0] * (K + 1)
    prev = 0
    for r in range(1, K + 1):
        tau[r] = max(prev + 1, D[r] + 1)
        prev = tau[r]
    out = []
    for T, A in queries:
        k = rank[A - 1]
        if k > K or tau[k] > T:
            out.append("Yes")
        else:
            out.append("No")
    return out

